class RetryBudget {
public:
    explicit RetryBudget(std::int32_t limit) : limit_{limit} {
        if (limit < 0) {
            std::terminate();  // Chapter 6 replaces this policy
        }
    }

    bool consume() {
        if (used_ == limit_) {
            return false;
        }
        ++used_;
        return true;
    }

    void reset() {
        used_ = 0;
    }

    std::int32_t remaining() const {
        return limit_ - used_;
    }

    friend std::ostream& operator<<(std::ostream& out, const RetryBudget& budget) {
        return out << budget.used_ << '/' << budget.limit_;
    }

private:
    std::int32_t limit_;
    std::int32_t used_{0};
};

#include <cstdint>

class ScopedCounter {
public:
    ScopedCounter() {
        ++live_;
    }

    ~ScopedCounter() {
        --live_;
    }

    // Declaring the destructor already suppressed both implicit moves. It did
    // NOT remove the implicit copies -- they are still generated, merely
    // deprecated -- and a copy would decrement twice for one increment, so the
    // copy operations are deleted explicitly.
    ScopedCounter(const ScopedCounter&) = delete;
    ScopedCounter& operator=(const ScopedCounter&) = delete;

    static std::int64_t live() {
        return live_;
    }

private:
    inline static std::int64_t live_ = 0;
};

