// Non-owning: callers may invoke through Sink* but cannot delete through it.
// The protected non-virtual destructor makes base-pointer deletion a compile
// error; derived objects are still destroyed through their concrete type.
class Sink {
public:
    virtual void on_chunk(const char* data, std::size_t size) = 0;

protected:
    ~Sink() = default;
};

// Owning: deletion through OwningSink* is part of the contract, so the
// destructor is public and virtual and selects the complete object's teardown.
class OwningSink {
public:
    virtual ~OwningSink() = default;
    virtual void on_chunk(const char* data, std::size_t size) = 0;
};

#include <cstdint>

// Internal packing under one ABI: compact and readable, but the bit positions
// are implementation-defined (allocation may start from either end), so this
// layout must never be written to a file or a socket.
struct SlotId {
    std::uint32_t epoch : 20;
    std::uint32_t index : 10;
    std::uint32_t dirty : 1;
    std::uint32_t reserved : 1;
};

static_assert(sizeof(SlotId) == 4);

// Explicit shifts and masks: the bit positions are stated in the source, so
// this form is the one that may cross a persistence or protocol boundary.
std::uint32_t pack_slot(std::uint32_t epoch, std::uint32_t index, bool dirty) {
    return (epoch & 0xF'FFFFu) | ((index & 0x3FFu) << 20) |
           (static_cast<std::uint32_t>(dirty) << 30);
}

std::uint32_t unpack_epoch(std::uint32_t word) {
    return word & 0xF'FFFFu;
}

