#include <iostream>

class Widget {
public:
    explicit Widget(int id) : id_{id} {}
    virtual ~Widget() = default;

    int id() const {
        return id_;
    }

private:
    int id_;
};

class Drawable : public virtual Widget {
public:
    explicit Drawable(int id) : Widget{id} {}
    virtual void draw() const = 0;
};

class Focusable : public virtual Widget {
public:
    explicit Focusable(int id) : Widget{id} {}
    virtual void focus() = 0;
};

class TextBox final : public Drawable, public Focusable {
public:
    // The most-derived class initializes a virtual base directly; the Widget
    // initializers written in Drawable and Focusable are ignored here.
    explicit TextBox(int id) : Widget{id}, Drawable{id}, Focusable{id} {}

    void draw() const override {
        std::cout << id() << '\n';  // unambiguous: one shared Widget subobject
    }

    void focus() override {}
};

#include <iostream>
#include <vector>

template <typename Derived>
class Chainable {
public:
    Derived& then(int step) {
        steps_.push_back(step);
        return static_cast<Derived&>(*this);
    }

    int total() const {
        int sum = 0;
        for (int step : steps_) {
            sum += step;
        }
        return sum;
    }

private:
    std::vector<int> steps_;
};

class Pipeline : public Chainable<Pipeline> {
public:
    Pipeline& name(const char* label) {
        label_ = label;
        return *this;
    }

    void run() const {
        std::cout << label_ << ' ' << total() << '\n';
    }

private:
    const char* label_ = "";
};

void demo() {
    Pipeline pipeline;
    pipeline.then(1).then(2).name("compact").run();
}
